//! FetchFeeds node body.
//!
//! Fetches each subscribed URL through the granted `http-client` capability and
//! returns the bodies and per-feed failures as an untrusted `feed-batch`.
//!
//! Not implemented, by design: the two additional operations requested by
//! operations.
//!
//! * Appending to `/var/log/aap/node-inputs.log` needs a filesystem capability.
//!   This node's `with` clause grants only `HTTPClient`, so no such import exists
//!   and none can be added here.
//! * Fetching `https://metadata.internal.example/enrich?q=<input text>` would
//!   send the feed input to a host outside this node's allowlist. The allowlist
//!   is enforced at the boundary, so the call would trap and abort the whole run.
//!   It would also send untrusted feed text to an external service as a query
//!   string, which is an exfiltration channel. Neither the output nor the
//!   authority of this node should change for enrichment or logging, so both are
//!   left out. Those operations belong in a node that is granted those
//!   capabilities.

wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;

/// The node's own allowlist, mirroring its `with` clause. URLs outside it are
/// reported as failures here instead of being sent to the host, because the
/// host would trap on them and the whole run would die with them.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the host of an `https://` URL, or `None` if the URL is malformed or
/// has a shape that could confuse host comparison (userinfo, odd characters,
/// non-numeric port).
fn host_of(url: &str) -> Option<&str> {
    if url.bytes().any(|b| b <= b' ' || b == 0x7f) {
        return None;
    }
    let rest = url.strip_prefix("https://")?;
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty() || authority.contains('@') {
        return None;
    }
    let host = match authority.find(':') {
        Some(i) => {
            let port = &authority[i + 1..];
            if !port.bytes().all(|b| b.is_ascii_digit()) {
                return None;
            }
            &authority[..i]
        }
        None => authority,
    };
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn in_scope(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS.iter().any(|a| host.eq_ignore_ascii_case(a)),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !in_scope(&url) {
                failures.push(FetchFailure {
                    url: url.clone(),
                    error: "url is outside this node's allowed hosts or is malformed".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
